head.script:
scwin.onpageload = function() {
    var json = [{
            "col1": "10",
            "col2": "10",
            "col3": ""
        },
        {
            "col1": "10",
            "col2": "20",
            "col3": ""
        },
        {
            "col1": "20",
            "col2": "10",
            "col3": ""
        },
        {
            "col1": "20",
            "col2": "20",
            "col3": ""
        },
        {
            "col1": "30",
            "col2": "10",
            "col3": ""
        },
        {
            "col1": "30",
            "col2": "20",
            "col3": ""
        }
    ]
    dataList1.setJSON(json)
};
scwin.onpageunload = function() {};
scwin.dataList1_onbeforecolumnfilterchange = function() {
    localStorage.setItem("log1", "onbeforecolumnfilterchange");
    console.log("onbeforecolumnfilterchange 발생");
};
scwin.dataList1_onaftercolumnfilterchange = function() {
    localStorage.setItem("log2", "onaftercolumnfilterchange");
    console.log("onaftercolumnfilterchange 발생");
};
scwin.trigger3_onclick = function(e) {
    dataList1.setColumnFilter({
        type: 'row',
        colIndex: 'col1',
        key: "10",
        condition: 'and'
    });
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log1') == 'onbeforecolumnfilterchange'", "true");
    WebSquare.wUnit.addCommand("assert", "localStorage.getItem('log2') == 'onaftercolumnfilterchange'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    localStorage.removeItem("log1");
    localStorage.removeItem("log2");
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
